const LANGUAGES=["Afrikaans","Albanian","Asturian","Asu","Basque","Bemba","Bena","Breton","Catalan","Chiga","Colognian","Cornish","Croatian","Czech","Danish","Dutch","Embu","English","Esperanto","Estonian","Faroese","Filipino","Finnish","French","Friulian","Galician","Ganda","German","Gusii","Hungarian","Icelandic","Igbo","Inari Sami","Indonesian","Irish","Italian","Jola-Fonyi","Kabuverdianu","Kalaallisut","Kalenjin","Kamba","Kikuyu","Kinyarwanda","Latvian","Lithuanian","Lower Sorbian","Luo","Luxembourgish","Luyia","Machame","Makhuwa-Meetto","Makonde","Malagasy","Maltese","Manx","Meru","Morisyen","Nama","Northern Sami","North Ndebele","Norwegian Bokmål","Norwegian Nynorsk","Nyankole","Oromo","Polish","Portuguese","Prussian","Quechua","Romanian","Romansh","Rombo","Rundi","Rwa","Samburu","Sango","Sangu","Scottish Gaelic","Sena","Serbian","Shambala","Shona","Slovak","Slovenian","Soga","Somali","Spanish","Swahili","Swedish","Swiss German","Taita","Teso","Turkish","Upper Sorbian","Uzbek (Latin)","Vietnamese","Volapük","Vunjo","Walser","Welsh","Western Frisian","Yoruba","Zulu"];
const axes={
  serf:{range:'serfRange',value:'serfValue',key:'SERF'},
  cntr:{range:'cntrRange',value:'cntrValue',key:'CNTR'},
  ital:{range:'italRange',value:'italValue',key:'ital'},
  wght:{range:'wghtRange',value:'wghtValue',key:'wght'},
  wdth:{range:'wdthRange',value:'wdthValue',key:'wdth'}
};

const VOICES={
  'serif-low':{SERF:1,CNTR:0},'serif-high':{SERF:1,CNTR:100},
  'sans-low':{SERF:0,CNTR:0},'sans-high':{SERF:0,CNTR:100}
};
const stylePresets={wght:{id:'weightPreset',values:[300,400,500,600,700]},wdth:{id:'widthPreset',values:[50,75,100,125,150]},ital:{id:'stylePreset',values:[0,1]}};
const DEFAULT_VARIABLE={SERF:1,CNTR:100,wght:400,wdth:100,ital:0};
let variableState={...DEFAULT_VARIABLE};
let animationFrame=null;
let animationStart=0;
const $=id=>document.getElementById(id);

function formatAxis(key,value){
  if(key==='SERF'||key==='ital') return Number(value).toFixed(2).replace(/\.00$/,'');
  return Number(value.toFixed(2));
}

function applyVariable(){
  const specimen=$('liveSpecimen');
  specimen.style.fontVariationSettings=`"SERF" ${variableState.SERF},"CNTR" ${variableState.CNTR},"wght" ${variableState.wght},"wdth" ${variableState.wdth},"ital" ${variableState.ital}`;
  const family=Object.entries(VOICES).find(([,voice])=>Math.abs(variableState.SERF-voice.SERF)<1e-6&&Math.abs(variableState.CNTR-voice.CNTR)<1e-6);
  const familyValue=family?family[0]:'custom';
  if($('familyPreset').value!==familyValue)$('familyPreset').value=familyValue;
  for(const [key,preset] of Object.entries(stylePresets)){
    const value=preset.values.find(value=>Math.abs(value-variableState[key])<1e-6);
    const selected=value===undefined?'custom':String(value);
    if($(preset.id).value!==selected)$(preset.id).value=selected;
  }
  Object.values(axes).forEach(axis=>{
    $(axis.range).value=variableState[axis.key];
    $(axis.value).value=formatAxis(axis.key,variableState[axis.key]);
  });
}

function stopAnimation(){
  if(animationFrame!==null){
    cancelAnimationFrame(animationFrame);
    animationFrame=null;
  }
  $('playVariable').textContent='Animate';
  $('playVariable').setAttribute('aria-label','Play variable animation');
  $('playVariable').setAttribute('aria-pressed','false');
}

Object.values(axes).forEach(axis=>$(axis.range).addEventListener('input',()=>{
  stopAnimation();
  variableState[axis.key]=parseFloat($(axis.range).value);
  applyVariable();
}));

$('familyPreset').addEventListener('change',()=>{
 const voice=VOICES[$('familyPreset').value];if(!voice)return;
 stopAnimation();Object.assign(variableState,voice);applyVariable();
});
Object.entries(stylePresets).forEach(([key,preset])=>$(preset.id).addEventListener('change',()=>{
 const value=Number($(preset.id).value);if(!preset.values.includes(value))return;
 stopAnimation();variableState[key]=value;applyVariable();
}));

function resetVariable(){
  stopAnimation();
  variableState={...DEFAULT_VARIABLE};
  applyVariable();
}

/* V5 interpolation path: staged movement inspired by the reference interpolation lab.
   Every target range is reached, but the axes peak at different moments so the
   specimen visibly changes character instead of simply becoming a single
   simultaneous max/min state. */
const animationFrames=[
  {t:0.00, SERF:0, CNTR:0,   wght:300, wdth:50,  ital:0},
  {t:0.25, SERF:0, CNTR:25,  wght:700, wdth:100, ital:0},
  {t:0.50, SERF:1, CNTR:100, wght:300, wdth:150, ital:0},
  {t:0.75, SERF:1, CNTR:35,  wght:700, wdth:100, ital:1},
  {t:1.00, SERF:0, CNTR:0,   wght:300, wdth:50,  ital:0}
];
const animationDuration=8000;

function ease(t){return t*t*(3-2*t)}
function lerp(a,b,t){return a+(b-a)*t}

function animateVariable(time){
  const elapsed=time-animationStart;
  const p=(elapsed%animationDuration)/animationDuration;

  let a=animationFrames[0];
  let b=animationFrames[1];

  for(let i=0;i<animationFrames.length-1;i++){
    if(p>=animationFrames[i].t && p<=animationFrames[i+1].t){
      a=animationFrames[i];
      b=animationFrames[i+1];
      break;
    }
  }

  const local=ease((p-a.t)/(b.t-a.t || 1));

  Object.keys(variableState).forEach(key=>{
    variableState[key]=lerp(a[key],b[key],local);
  });

  applyVariable();
  animationFrame=requestAnimationFrame(animateVariable);
}

function startAnimation(){
  if(animationFrame!==null)return;
  $('playVariable').textContent='Pause';
  $('playVariable').setAttribute('aria-label','Pause variable animation');
  $('playVariable').setAttribute('aria-pressed','true');
  animationStart=performance.now();
  animationFrame=requestAnimationFrame(animateVariable);
}

$('playVariable').addEventListener('click',()=>animationFrame!==null?stopAnimation():startAnimation());
$('resetVariable').addEventListener('click',resetVariable);

const compactScreen=matchMedia('(max-width:800px)');
const DEFAULT_SPECIMEN={size:compactScreen.matches?48:96,leading:1.1,tracking:-0.025};
for(const [range,input,key] of [['sizeRange','sizeInput','size'],['leadingRange','leadingInput','leading'],['trackingRange','trackingInput','tracking']]){$(range).value=DEFAULT_SPECIMEN[key];$(input).value=$(range).value;}
function applySpecimenControls(){
  const specimen=$('liveSpecimen');
  specimen.style.fontSize=$('sizeRange').value+'px';
  specimen.style.lineHeight=$('leadingRange').value;
  specimen.style.letterSpacing=$('trackingRange').value+'em';
}
function syncSpecimenControl(rangeId,inputId){
  const range=$(rangeId),input=$(inputId);
  range.addEventListener('input',()=>{input.value=range.value;applySpecimenControls()});
  function commitValue(){
    const value=input.valueAsNumber;
    range.value=Number.isFinite(value)?String(Math.min(Number(range.max),Math.max(Number(range.min),value))):range.value;
    input.value=range.value;
    applySpecimenControls();
  }
  input.addEventListener('input',()=>{
    // Keep incomplete typing intact; commit and bound it on Enter or blur.
    const value=input.valueAsNumber;
    if(!Number.isFinite(value)||value<Number(range.min)||value>Number(range.max)) return;
    range.value=String(value);
    applySpecimenControls();
  });
  input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();commitValue()}});
  input.addEventListener('change',commitValue);
  input.addEventListener('blur',commitValue);
}
syncSpecimenControl('sizeRange','sizeInput');
syncSpecimenControl('leadingRange','leadingInput');
syncSpecimenControl('trackingRange','trackingInput');
$('resetSpecimen').addEventListener('click',()=>{
  $('sizeRange').value=DEFAULT_SPECIMEN.size; $('sizeInput').value=DEFAULT_SPECIMEN.size;
  $('leadingRange').value=DEFAULT_SPECIMEN.leading; $('leadingInput').value=DEFAULT_SPECIMEN.leading;
  $('trackingRange').value=DEFAULT_SPECIMEN.tracking; $('trackingInput').value=DEFAULT_SPECIMEN.tracking;
  applySpecimenControls();
});
let activeGlyphSection=Object.keys(SECTIONS)[0];
const glyphPreview=$("glyphPreview");
const glyphPreviewName=$("glyphPreviewName");
const glyphPreviewCategory=$("glyphPreviewCategory");
function showGlyphPreview(char,category,cell){
  if(cell){
    document.querySelectorAll('.glyph[aria-pressed="true"]').forEach(item=>item.setAttribute('aria-pressed','false'));
    cell.setAttribute('aria-pressed','true');
  }
  glyphPreview.textContent=char;
  const codes=Array.from(char,c=>'U+'+c.codePointAt(0).toString(16).toUpperCase().padStart(4,'0')).join(' ');
  glyphPreviewName.textContent=char+' · '+codes;
  glyphPreviewName.title=codes;
  glyphPreviewCategory.textContent=category;
}
function renderGlyphs(){
  const box=$("glyphGroups");
  box.innerHTML="";
  Object.entries(SECTIONS).forEach(([name,chars],index)=>{
    const section=document.createElement("div");
    section.className=`glyph-group${index===0?" is-open":""}`;

    const title=document.createElement("button");
    title.className="glyph-title";
    title.type="button";
    title.setAttribute("aria-expanded",index===0?"true":"false");
    title.setAttribute("aria-controls",`glyph-grid-${index}`);
    title.innerHTML=`<span>${name}</span><small>${chars.length} glyphs</small>`;

    const grid=document.createElement("div");
    grid.className="glyph-grid";
    grid.id=`glyph-grid-${index}`;
    grid.hidden=index!==0;

    title.addEventListener("click",()=>{
      const open=section.classList.toggle("is-open");
      title.setAttribute("aria-expanded",String(open));
      grid.hidden=!open;
    });

    const heading=document.createElement("h3");
    heading.appendChild(title);
    chars.forEach((c,cellIndex)=>{
      const cell=document.createElement("button");
      cell.className="glyph";
      cell.type="button";
      cell.textContent=c;
      cell.setAttribute("aria-label",`Glyph ${c}`);
      cell.setAttribute("aria-pressed",String(index===0 && cellIndex===0));
      cell.addEventListener("mouseenter",()=>showGlyphPreview(c,name,cell));
      cell.addEventListener("pointerdown",()=>showGlyphPreview(c,name,cell),{passive:true});
      cell.addEventListener("focus",()=>showGlyphPreview(c,name,cell));
      cell.addEventListener("click",()=>showGlyphPreview(c,name,cell));
      grid.appendChild(cell);
    });

    section.append(heading,grid);
    box.appendChild(section);
  });
}
function renderLanguages(){$('languageList').innerHTML=LANGUAGES.map(x=>`<span>${x}</span>`).join(' · ')}
showGlyphPreview(SECTIONS[activeGlyphSection][0],activeGlyphSection);
renderGlyphs();renderLanguages();applyVariable();applySpecimenControls();

$('preview-count').textContent=Object.values(SECTIONS).reduce((total,chars)=>total+chars.length,0).toLocaleString('en-US')+' preview entries';
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
const heroTitle=document.querySelector('.bia-variable');
const heroToggle=$('toggleHeroMotion');
function setHeroPaused(paused){
  heroTitle.style.animationPlayState=paused?'paused':'running';
  heroToggle.setAttribute('aria-pressed',String(paused));
  const label=paused?'Play title animation':'Pause title animation';
  heroToggle.setAttribute('aria-label',label);
  heroToggle.title=label;
  heroToggle.querySelector('span').textContent=paused?'▶':'Ⅱ';
}
heroToggle.addEventListener('click',()=>setHeroPaused(heroToggle.getAttribute('aria-pressed')!=='true'));
reducedMotion.addEventListener('change',()=>{stopAnimation();setHeroPaused(reducedMotion.matches)});
document.addEventListener('visibilitychange',()=>{
  if(document.hidden){stopAnimation();heroTitle.style.animationPlayState='paused'}
  else setHeroPaused(heroToggle.getAttribute('aria-pressed')==='true');
});
setHeroPaused(reducedMotion.matches);

function updateComparison(){
  const text=$('compareText').value;
  for(const side of ['left','right']){
    const voice=VOICES[$('compare-'+side).value];
    const preview=$('compare-preview-'+side);
    preview.textContent=text;
    preview.style.fontVariationSettings='"SERF" '+voice.SERF+',"CNTR" '+voice.CNTR+',"wght" 400,"wdth" 100,"ital" 0';
  }
}
$('compareText').addEventListener('input',updateComparison);
document.querySelectorAll('[data-compare-side]').forEach(select=>select.addEventListener('change',updateComparison));
updateComparison();
/* Bia's verified features; v1 saved combinations remain restorable. */
const FEATURE_DEFAULTS={liga:true,dlig:false,ss01:false,ss02:false,frac:false};
let featureState={...FEATURE_DEFAULTS};
const FEATURE_SAMPLES={dlig:'BY',ss01:'A different point of view.',ss02:'ELEGANCE',frac:'1/2 3/4'};
function applyFeatures(){
 if(featureState.ss01&&featureState.ss02)featureState.ss01=false;
 $('liveSpecimen').style.fontFeatureSettings=Object.entries(featureState).map(([tag,on])=>'"'+tag+'" '+Number(on)).join(',');
 let selected='custom';
 if(Object.keys(FEATURE_DEFAULTS).every(tag=>featureState[tag]===FEATURE_DEFAULTS[tag]))selected='original';
 else for(const tag of Object.keys(FEATURE_SAMPLES)){
  const expected={...FEATURE_DEFAULTS,[tag]:true};
  if(Object.keys(expected).every(key=>featureState[key]===expected[key])){selected=tag;break;}
 }
 $('featurePreset').value=selected;
 $('tryFeatures').hidden=!FEATURE_SAMPLES[selected];
}
$('featurePreset').addEventListener('change',()=>{
 const tag=$('featurePreset').value;featureState={...FEATURE_DEFAULTS};
 if(FEATURE_SAMPLES[tag])featureState[tag]=true;
 applyFeatures();
});
$('tryFeatures').addEventListener('click',()=>{
 const sample=FEATURE_SAMPLES[$('featurePreset').value];if(sample)$('liveSpecimen').textContent=sample;
});
applyFeatures();

/* Search the existing preview entries without changing the repertoire. */
const searchGroups=[...document.querySelectorAll('#glyphGroups .glyph-group')];
let groupStateBeforeSearch=null;
let selectedBeforeSearch=null;
function filterCharacters(){
  const query=$('glyphSearch').value.trim();
  const normalized=query.toLowerCase();
  if(query && !groupStateBeforeSearch){
    groupStateBeforeSearch=searchGroups.map(group=>group.classList.contains('is-open'));
    selectedBeforeSearch=document.querySelector('#glyphGroups .glyph[aria-pressed="true"]');
  }
  let total=0;
  let firstMatch=null;
  searchGroups.forEach((group,index)=>{
    const cells=[...group.querySelectorAll('.glyph')];
    const title=group.querySelector('.glyph-title');
    const category=title.querySelector('span').textContent;
    let matches=0;
    cells.forEach(cell=>{
      const char=cell.textContent;
      const codes=Array.from(char,c=>'U+'+c.codePointAt(0).toString(16).toUpperCase().padStart(4,'0')).join(' ');
      const names=Array.from(char,c=>CHARACTER_NAMES[c]||'').join(' ');
      const found=!query || (Array.from(query).length===1?char===query:(char+' '+codes+' '+names+' '+category).toLowerCase().includes(normalized));
      cell.hidden=!found;
      if(found){matches++;if(!firstMatch)firstMatch=cell;}
    });
    total+=matches;
    group.hidden=matches===0;
    const open=query?matches>0:(groupStateBeforeSearch?groupStateBeforeSearch[index]:group.classList.contains('is-open'));
    group.classList.toggle('is-open',open);
    title.setAttribute('aria-expanded',String(open));
    group.querySelector('.glyph-grid').hidden=!open;
    title.querySelector('small').textContent=query?matches+' results':cells.length+' glyphs';
  });
  $('glyphSearchStatus').textContent=query?(total?total+' matching preview entries':'No matching characters. Try a character, Unicode code, or category.'):'';
  const selected=query?firstMatch:selectedBeforeSearch;
  if(selected){
    const category=selected.closest('.glyph-group').querySelector('.glyph-title span').textContent;
    showGlyphPreview(selected.textContent,category,selected);
  }else if(query){
    document.querySelectorAll('.glyph[aria-pressed="true"]').forEach(cell=>cell.setAttribute('aria-pressed','false'));
    glyphPreview.textContent='—';glyphPreviewName.textContent='No matching character';glyphPreviewCategory.textContent='';
  }
  if(!query){groupStateBeforeSearch=null;selectedBeforeSearch=null;}
}
$('glyphSearch').addEventListener('input',filterCharacters);
$('clearGlyphSearch').addEventListener('click',()=>{$('glyphSearch').value='';filterCharacters();$('glyphSearch').focus()});

/* Save explicitly on this browser; shared state stays in the URL fragment. */
const STORAGE_KEY='bykineks-bia-playground-v1';
function collectSetting(){
  const text=$('liveSpecimen').textContent;
  if(text.length>5000)throw new Error('Use 5,000 characters or fewer to save or share a setting.');
  return {v:1,text,axes:{...variableState},size:Number($('sizeRange').value),leading:Number($('leadingRange').value),tracking:Number($('trackingRange').value),features:{...featureState}};
}
function restoreSetting(state){
  if(!state||state.v!==1||typeof state.text!=='string'||state.text.length>5000||!state.axes)throw new Error('This setting could not be restored.');
  for(const axis of Object.values(axes)){
    const value=state.axes[axis.key];
    if(typeof value!=='number'||!Number.isFinite(value))throw new Error('This setting has invalid axis values.');
  }
  for(const key of ['size','leading','tracking'])if(typeof state[key]!=='number'||!Number.isFinite(state[key]))throw new Error('This setting has invalid text values.');
  stopAnimation();
  for(const axis of Object.values(axes)){
    const range=$(axis.range);
    range.value=String(Math.min(Number(range.max),Math.max(Number(range.min),state.axes[axis.key])));
    variableState[axis.key]=Number(range.value);
  }
  $('liveSpecimen').textContent=state.text;
  for(const [range,input,key] of [['sizeRange','sizeInput','size'],['leadingRange','leadingInput','leading'],['trackingRange','trackingInput','tracking']]){
    $(range).value=String(state[key]);$(input).value=$(range).value;
  }
  featureState=Object.fromEntries(Object.entries(FEATURE_DEFAULTS).map(([tag,value])=>[tag,state.features&&typeof state.features[tag]==='boolean'?state.features[tag]:value]));
  applyVariable();applySpecimenControls();applyFeatures();
}
function setSettingStatus(message){$('settingStatus').textContent=message;}
$('saveSetting').addEventListener('click',()=>{
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify(collectSetting()));$('loadSetting').disabled=false;setSettingStatus('Saved on this browser. Your text and settings stay on this device.');}
  catch(error){setSettingStatus(error.message.startsWith('Use 5,000')?error.message:'Saving is unavailable in this browser. You can still copy a setting link.');}
});
$('loadSetting').addEventListener('click',()=>{
  try{restoreSetting(JSON.parse(localStorage.getItem(STORAGE_KEY)));setSettingStatus('Saved playground setting restored.');}
  catch{setSettingStatus('The saved setting could not be restored. Save a new setting to replace it.');}
});
$('copySetting').addEventListener('click',async()=>{
  let link;
  try{const url=new URL(location.href);url.hash='bia='+encodeURIComponent(JSON.stringify(collectSetting()));link=url.href;}
  catch(error){setSettingStatus(error.message);return;}
  try{await navigator.clipboard.writeText(link);$('settingLinkFallback').hidden=true;setSettingStatus('Setting link copied. It includes your specimen text and settings.');}
  catch{$('settingLinkFallback').hidden=false;$('settingLink').value=link;$('settingLink').focus();$('settingLink').select();setSettingStatus('Copy the link below. It includes your specimen text and settings.');}
});
try{$('loadSetting').disabled=!localStorage.getItem(STORAGE_KEY)}catch{$('loadSetting').disabled=true}
function loadSharedSetting(){
  if(!location.hash.startsWith('#bia='))return;
  try{restoreSetting(JSON.parse(decodeURIComponent(location.hash.slice(5))));setSettingStatus('Shared playground setting restored.');$('system').scrollIntoView({behavior:'instant',block:'start'});}
  catch{setSettingStatus('This shared setting could not be restored. The current preview is ready to use.');}
}
window.addEventListener('hashchange',loadSharedSetting);
loadSharedSetting();
